class Sampler:
    """模拟大模型采样：温度 0 贪心，高温在候选间轮换。"""

    def __init__(self, candidates):
        self.candidates = candidates

    def next_token(self, temperature):
        if temperature == 0:
            return self.candidates[0]
        index = temperature % len(self.candidates)
        return self.candidates[index]

    def top_k(self, k=2):
        return self.candidates[:k]

