def estimate_tokens(text):
    """4 字符 ≈ 1 token 的粗估，至少计 1。"""
    return max(1, len(text) // 4)


class TokenBudget:
    def __init__(self, total):
        self.total = total
        self.used = 0

    def try_consume(self, text):
        cost = estimate_tokens(text)
        if self.used + cost > self.total:
            return False
        self.used += cost
        return True

