class ToolRegistry:
    """工具注册表：注册、生成提示词清单、按名执行。"""

    def __init__(self):
        self._tools = {}

    def register(self, name, fn, description):
        self._tools[name] = {"fn": fn, "description": description}

    def as_prompt(self):
        lines = ["你可以使用以下工具:"]
        for name, tool in self._tools.items():
            lines.append(f"- {name}: {tool['description']}")
        return "\n".join(lines)

    def run(self, tool_name, **kwargs):
        if tool_name not in self._tools:
            return f"错误: 未注册的工具 {tool_name}"
        return self._tools[tool_name]["fn"](**kwargs)


