class RetrievalPipeline:
    """初检负责召回，重排负责把最相关的排到前面。"""

    def __init__(self, corpus):
        self.corpus = corpus

    def initial_search(self, query, k=4):
        return [c for c in self.corpus if query in c][:k]

    def rerank(self, query, candidates):
        def score(chunk):
            s = chunk.count(query) * 2
            if chunk.startswith(query):
                s += 3
            if query in chunk[:8]:
                s += 1
            return s
        return sorted(candidates, key=score, reverse=True)

    def query(self, q, k=4):
        return self.rerank(q, self.initial_search(q, k))[:2]

