def pack(system, retrieved, history, budget=30):
    est = lambda t: len(t) // 4 + 1
    parts = [("system", system)]
    used = est(system)
    for text in retrieved:
        if used + est(text) > budget:
            continue
        parts.append(("rag", text))
        used += est(text)
    for text in history:
        if used + est(text) > budget:
            break
        parts.append(("history", text))
        used += est(text)
    return parts, used

