import json
import re

reply = '调用 get_weather，参数 {"city": "上海"}'

def parse_call(reply, tools):
    for name in tools:
        if name in reply:
            m = re.search(r"\{.*\}", reply)
            args = json.loads(m.group(0)) if m else {}
            return {"name": name, "arguments": args}
    return None

call = parse_call(reply, ["get_weather", "get_time"])
if call:
    print("工具:", call["name"], "| 参数:", call["arguments"])
else:
    print("没有工具调用")

SCHEMA = {
    "priority": {"enum": ["low", "medium", "high"]},
    "size": {"min": 1, "max": 10},
}

def validate(data):
    errors = []
    if data.get("priority") not in SCHEMA["priority"]["enum"]:
        errors.append("priority 非法")
    if not (SCHEMA["size"]["min"] <= data.get("size", 0) <= SCHEMA["size"]["max"]):
        errors.append("size 越界")
    return errors

for data in ({"priority": "urgent", "size": 5}, {"priority": "low", "size": 3}):
    errors = validate(data)
    print(data["priority"], "->", "校验通过" if not errors else errors)

