class Pipeline:
    """把多个智能体按顺序串成流水线。"""

    def __init__(self, *agents):
        self.agents = agents

    def run(self, payload):
        for agent in self.agents:
            payload = agent(payload)
            print(f"  [{agent.__name__}] -> {payload}")
        return payload

