class RouterAgent:
    AGENTS = {"technical": "技术客服", "billing": "账单客服"}
    RULES = {"technical": ("报错", "崩溃", "故障"), "billing": ("发票", "退款", "账单")}

    def classify(self, text):
        for intent, keywords in self.RULES.items():
            if any(kw in text for kw in keywords):
                return intent
        return "billing"

    def handle(self, text):
        name = self.AGENTS[self.classify(text)]
        return f"{name} 处理: {text}"

