class MessageBus:
    def __init__(self):
        self.inboxes = {}

    def register(self, name):
        self.inboxes[name] = []

    def send(self, to, msg):
        self.inboxes[to].append(f"收到: {msg}")

    def broadcast(self, msg, *targets):
        for t in targets:
            self.send(t, msg)

