class Debate:
    """正反方轮流发言，裁判按票数裁定。"""

    def __init__(self, rounds=2):
        self.rounds = rounds
        self.transcript = []
        self.votes = {}

    def speech(self, side, r):
        return f"{side}第{r}轮: 坚持立场并反驳对方"

    def run(self):
        for r in range(1, self.rounds + 1):
            for side in ("正方", "反方"):
                self.transcript.append((side, self.speech(side, r)))
                self.votes[side] = self.votes.get(side, 0) + (2 if r == self.rounds else 1)

debate = Debate(rounds=2)
debate.run()
verdict = max(debate.votes.items(), key=lambda kv: kv[1])[0]
print("发言数:", len(debate.transcript), "| 票数:", debate.votes)
print("裁判裁定:", verdict)

def reviewer(draft):
