class RetryWithBackoff:
    """指数退避：1s → 2s → 4s，重试耗尽明确放弃。"""

    def __init__(self, failures):
        self.failures = list(failures)

    def call(self):
        delays = (1, 2, 4)
        for attempt, delay in enumerate(delays, 1):
            outcome = self.failures.pop(0) if self.failures else "成功"
            if outcome == "成功":
                return f"第 {attempt} 次成功，累计退避 {sum(delays[:attempt - 1])}s"
            print(f"第 {attempt} 次失败: {outcome}，退避 {delay}s 后重试")
        return "重试耗尽，放弃本次任务"

retry = RetryWithBackoff(["限流", "超时"])
print(retry.call())
empty = RetryWithBackoff([])
print(empty.call())

class CostLedger:
    PRICE = {"input": 0.001, "output": 0.002}  # 每千 token 单价

    def __init__(self, budget=1.0):
        self.total = 0.0
        self.budget = budget

    def add(self, input_tokens, output_tokens):
        cost = (input_tokens + output_tokens) / 1000 * self.PRICE["input"]
        cost += output_tokens / 1000 * self.PRICE["output"]
        self.total += cost
        return round(cost, 6)

    @property
    def over_budget(self):
        return self.total > self.budget

ledger = CostLedger(budget=0.01)
for i, (inp, out) in enumerate([(1200, 500), (3000, 1500), (5000, 4000)], 1):
    cost = ledger.add(inp, out)
    print(f"调用 {i}: 本次 {cost} 元 | 累计 {round(ledger.total, 4)} 元")
print("超预算:", ledger.over_budget)

class Trace:
    def __init__(self):
        self.entries = []

    def log(self, step, detail):
        self.entries.append(f"step{step}: {detail}")

    def report(self):
        return "\n".join(f"{i}. {t}" for i, t in enumerate(self.entries, 1))

